const updateFaceCluster = `-- name: UpdateFaceCluster :one
UPDATE face_clusters
SET
    cluster_name = ?2,
    confidence_score = ?3,
    is_confirmed = ?4,
    updated_at = CAST(unixepoch('subsec') * 1000000 AS INTEGER)
WHERE cluster_id = ?1
RETURNING cluster_id, owner_id, cluster_name, representative_face_id, confidence_score, member_count, is_confirmed, is_hidden, hidden_at, created_at, updated_at
`

type UpdateFaceClusterParams struct {
	ClusterID       int32   `db:"cluster_id" json:"cluster_id"`
	ClusterName     *string `db:"cluster_name" json:"cluster_name"`
	ConfidenceScore float64 `db:"confidence_score" json:"confidence_score"`
	IsConfirmed     bool    `db:"is_confirmed" json:"is_confirmed"`
}

func (q *Queries) UpdateFaceCluster(ctx context.Context, arg UpdateFaceClusterParams) (FaceCluster, error) {
	row := q.db.QueryRowContext(ctx, updateFaceCluster,
		arg.ClusterID,
		arg.ClusterName,
		arg.ConfidenceScore,
		arg.IsConfirmed,
	)
	var i FaceCluster
	err := row.Scan(
		&i.ClusterID,
		&i.OwnerID,
		&i.ClusterName,
		&i.RepresentativeFaceID,
		&i.ConfidenceScore,
		&i.MemberCount,
		&i.IsConfirmed,
		&i.IsHidden,
		&i.HiddenAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
